// Owned editor guidance and exact diagnostic messages. Raw source data stays literal.
const entries = [];
const add = (id, en, de, fr, es, code, caption) => entries.push(Object.freeze({ key: `editorDetails.${id}`, en, de, fr, es,
  ...(code === undefined ? {} : { message: true, code }), ...caption }));
const caption = (id, selector, kind, ...words) => add(`overlay.${id}`, ...words, undefined, { selector, kind });
const field = (id, ...words) => caption(`field.${id}`, `[data-field="ovr-${id}"]`, 'label', ...words);
const action = (id, ...words) => caption(`action.${id}`, `[data-act="ovr-${id}"]`, 'text', ...words);
const choice = (field, value, ...words) => caption(`choice.${field}.${value || 'choose'}`, `[data-field="ovr-${field}"] option[value="${value}"]`, 'text', ...words);
add('shading.intro', 'Choose how the card displays your model. These choices do not bake new shadows or change your real lights.', 'Wählen Sie die Darstellung Ihres Modells. Diese Optionen berechnen keine gebackenen Schatten und ändern keine echten Lampen.', 'Choisissez l’affichage du modèle. Ces options ne précalculent pas les ombres et ne modifient pas vos vraies lumières.', 'Elija cómo se muestra el modelo. Estas opciones no precalculan sombras ni cambian sus luces reales.');
add('shading.policyHelp', 'No realtime shadows stops computed shadows. Authored shading also turns off the card’s lamp illumination; existing textures remain. Materials that use scene lighting still respond to the sun and ambient light.', 'Keine Echtzeitschatten schaltet berechnete Schatten aus. Modellschattierung schaltet auch das Lampenlicht der Karte aus; vorhandene Texturen bleiben. Beleuchtete Materialien reagieren weiter auf Sonne und Umgebungslicht.', 'Sans ombres en temps réel désactive les ombres calculées. L’ombrage du modèle coupe aussi l’éclairage des lampes de la carte ; les textures restent. Les matériaux éclairés réagissent toujours au soleil et à la lumière ambiante.', 'Sin sombras en tiempo real desactiva las sombras calculadas. El sombreado del modelo también apaga la iluminación de las lámparas de la tarjeta; las texturas permanecen. Los materiales iluminados siguen respondiendo al sol y a la luz ambiental.');
add('shading.noModel', 'No model is loaded. You can save a display choice now; it will also apply when a model is loaded.', 'Kein Modell geladen. Sie können eine Darstellung speichern; sie gilt auch nach dem Laden eines Modells.', 'Aucun modèle chargé. Vous pouvez enregistrer un choix d’affichage ; il s’appliquera aussi au prochain modèle chargé.', 'No hay un modelo cargado. Puede guardar una opción de visualización; también se aplicará cuando se cargue un modelo.');
